mapper.select:

where task_type = 'VIDEO' and provider_code = #{providerCode}
  and provider_task_id = #{providerTaskId}
  and (del_flag = '0' or del_flag is null)
limit 1

select task_id, project_id, chapter_id, asset_id, task_type, task_name, status,
       idempotency_key, provider_code, model_code, provider_task_id, progress,
       max_retry, retry_count, next_retry_time, request_json,
       error_code, error_message, callback_event_id, create_time
from ai_video_generation_task

    (del_flag = '0' or del_flag is null)
    and project_id = #{projectId}
    and task_type = #{taskType}
    and status = #{status}

order by task_id desc
